"""Read-only access to the solution-free case export (generated by `npm run export:cases`)."""
import json
from functools import lru_cache
from pathlib import Path
from typing import Any

DATA = Path(__file__).resolve().parent.parent / "case_data" / "public_cases.json"


@lru_cache
def load_cases() -> list[dict[str, Any]]:
    with DATA.open(encoding="utf-8") as fh:
        return json.load(fh)["cases"]


def get_case(case_id: str) -> dict[str, Any] | None:
    return next((c for c in load_cases() if c["id"] == case_id or c["slug"] == case_id), None)


def case_summary(c: dict[str, Any]) -> dict[str, Any]:
    keys = ("id", "slug", "number", "title", "tagline", "difficulty", "estimatedMinutes", "categories")
    return {k: c[k] for k in keys} | {"evidenceCount": len(c["evidence"])}
